begin;
update licoes set explicacao = 'Para dizer que algo pertence a alguém, use ''s: "Peter''s car" (o carro do Peter). É a forma mais comum de posse em inglês. Referência rápida — John + ''s = John''s; Tom + ''s = Tom''s; boy + ''s = boy''s; friend + ''s = friend''s.' where id = '19d7e1da-7366-4dd3-b368-e1402c0fa79b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Roupas comuns: shirt (camisa), pants (calça), shoes (sapatos), dress (vestido), jacket (jaqueta). Referência rápida — Pants / trousers = Calça; wear = usar (roupa); Jaqueta/casaco = Jacket / coat.' where id = '670f9640-cb27-405b-a4dc-c04d8a3579e0' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Ordinais indicam ordem e posição: first (1º), second (2º), third (3º). A maioria adiciona ''-th'': fourth, fifth. Referência rápida — Third = Terceiro; nine → ninth (sem o ''e'').' where id = '9a019fa0-82f2-4af5-8e1b-99cc4b7f0404' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O presente simples descreve rotinas e fatos. Na 3ª pessoa (he/she/it) o verbo ganha ''-s'': I work / she works. Referência rápida — I → drink; They → study.' where id = '0cc1bc00-02a2-4ed2-8da2-4f1db2e2e283' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Vocabulário da casa: kitchen (cozinha), bedroom (quarto), bathroom (banheiro), living room (sala). Referência rápida — Garagem = Garage; Jardim/quintal = Garden / yard.' where id = '3bed08b4-ffd0-4338-8c8e-b0c095d790f4' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Objetos comuns da casa: table (mesa), chair (cadeira), bed (cama), sofa (sofá), door (porta), window (janela). Referência rápida — Sofa / couch = Sofá; Geladeira = Fridge.' where id = 'd468f4cf-047f-4118-bcae-451337c57ed4' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'A maioria adiciona ''-s''. Palavras terminadas em -s, -ss, -sh, -ch, -x adicionam ''-es''. Algumas são irregulares. Referência rápida — -y vira -ies: city → cities.' where id = 'bc6a7ddb-5ef4-45f4-b8f3-9ff790294536' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Use ''There is'' para singular e incontáveis, e ''There are'' para plural. Significa ''há / existe(m)''. Referência rápida — Há muitos alunos = There are many students.' where id = 'e75d352a-6038-4d74-9b92-c69741c00506' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Pronomes pessoais substituem o nome de quem faz a ação: I, you, he, she, it, we, you, they. Referência rápida — We = Nós.' where id = '8769f8c8-5a9a-4ee8-beee-9b8ce566ca5d' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'A negativa usa don''t (I/you/we/they) ou doesn''t (he/she/it) + o verbo na forma base. Referência rápida — don''t = do not.' where id = 'fcb29365-a24d-4d70-a2c6-5b46a5b157da' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O imperativo dá ordens, instruções e pedidos. Use o verbo na forma base, sem sujeito: ''Open the door.'' Referência rápida — Turn right = Vire à direita.' where id = '0f94ea4d-b1c7-49c4-9e1d-fa2d5c2674b7' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Para sentimentos e estados, use ''be'' ou ''feel'': ''I am tired.'' / ''I feel happy.'' Referência rápida — Bored = Entediado.' where id = 'ba7c48da-6567-4b27-8967-1f6a420149a9' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Para dizer o que sente ao médico: ''I have a headache.'' (dor de cabeça). ''My ___ hurts.'' (dói). Referência rápida — estou doente = I am sick.' where id = '8159116f-bb41-4dfb-9a2c-2aa9817c312c' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Os números de 1 a 20 são a base para contar, dizer idade, horas e quantidades em inglês. Referência rápida — 8 = eight.' where id = '9a30e385-ff30-4660-b1f9-ffbf1d3f64de' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Para dizer a origem: "I''m from Brazil. I''m Brazilian." O país e a nacionalidade são palavras diferentes. Sempre com maiúscula. Referência rápida — USA → American.' where id = 'fa6b768a-ea64-4d98-aff8-413fff459a72' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Advérbios de modo dizem COMO algo é feito. Geralmente adjetivo + -ly: quick→quickly, careful→carefully. Irregulares: good→well, fast→fast. Referência rápida — clear → clearly.' where id = '27eba3d7-4acf-4352-9c6b-dc58efe95481' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Conectores ligam ideias: because (porque, causa), so (então, consequência), but (mas, contraste), although (embora, contraste forte). Referência rápida — because = razão.' where id = '2b655827-46a8-4d1f-92e8-75bed1e5852e' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'REMEMBER = lembrar (de algo, você mesmo). REMIND = lembrar alguém / fazer recordar. ''Remind me'' = me lembre. Referência rápida — I remember his name = Eu lembro do nome dele.' where id = 'a96dbde2-d388-461c-976f-2d3e6e37deba' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'JOB = emprego (contável: a job, two jobs). WORK = trabalho (incontável, não usa ''a work''). Também ''work'' é verbo (trabalhar). Referência rápida — Estou procurando emprego = I''m looking for a job.' where id = '06d2b5c6-34a8-45b7-b289-0f499b3b3f4b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'FUN = divertido/prazeroso (algo que dá prazer). FUNNY = engraçado (que faz rir) — ou estranho. Não confunda: uma festa é ''fun''; uma piada é ''funny''. Referência rápida — Foi super divertido = It was a lot of fun.' where id = '631c7bcb-286e-4cb8-879f-762dab06c214' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Conectam informação extra: ''who'' para pessoas, ''which'' para coisas, ''that'' para ambos. Referência rápida — where = lugar; whose = de quem (posse); when = tempo.' where id = '13da0cb4-bddc-4e1a-beac-d2916fc773ac' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'BRING = trazer (para perto de quem fala). TAKE = levar (para longe de quem fala). Depende do ponto de referência. Referência rápida — Take this to her = Leve isto para ela; bring → brought; take → took.' where id = '9261fff3-78b8-4902-ba80-291617e4511e' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Palavras que indicam quando algo aconteceu no passado: yesterday (ontem), ago (atrás), last (passado). Referência rápida — Last night = Ontem à noite; last month = mês passado.' where id = '5a1240b7-1a20-460d-be8d-ebe74c203a58' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Use o presente contínuo (am/is/are + verbo-ing) para descrever cenas e ações em andamento. Referência rápida — run → running; write → writing.' where id = '113d9ed5-0641-48ba-aa4f-2f7c5e3ed9aa' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Vocabulário escolar: degree (diploma), subject (matéria), exam (prova), homework (lição), graduate (formar-se). Referência rápida — Degree = Diploma/grau; Homework = lição de casa.' where id = '6df090f2-a662-4031-84ff-a3af58c53599' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Simple Present para rotinas e fatos. Present Continuous (am/is/are + verbo-ing) para algo acontecendo AGORA. Referência rápida — Every Sunday = rotina: play.' where id = '9b65f8a4-2737-40d3-9d9c-442e3c7d3e02' and explicacao not like '%Referência rápida%';
update licoes set explicacao = '''Be going to + verbo'' para planos e intenções, e para previsões com evidência clara. Referência rápida — She → is going to.' where id = 'f93d67bf-5f17-44cf-907d-7b5b96515992' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O passado do verbo To Be: I/he/she/it → was; you/we/they → were. Significa ''era / estava / foi''. Referência rápida — wasn''t = was not.' where id = '0ba48b99-043c-4323-99cd-5b474342a855' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Advérbios de modo dizem COMO algo é feito. Geralmente adjetivo + ''-ly'': quick → quickly. ''Good'' vira ''well''. Referência rápida — ''hard'' é igual (hardly = quase não).' where id = '30ec9703-e7e7-4aad-b103-3452f326b286' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Contáveis têm plural e número (an apple, two apples). Incontáveis não (water, money, rice) — não dizemos ''two waters''. Referência rápida — chair = contável.' where id = 'c0373df3-bbdc-459e-bb61-6035f8cfd77b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Frases ao telefone: ''Can I speak to...?'', ''Who''s calling?'', ''Hold on, please.'', ''Can I take a message?'' Referência rápida — The line is busy = A linha está ocupada.' where id = '7a5f6862-cab2-4d16-8593-a78806f2fa58' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Para combinar encontros: ''Are you free on Friday?'', ''Let''s meet at 3.'', ''How about Monday?'' Referência rápida — reschedule = remarcar.' where id = '62ad05b1-d2e6-4c32-aea8-99b8f932e2bb' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Vocabulário verde: pollution (poluição), recycle (reciclar), climate change (mudança climática), waste (desperdício/lixo). Referência rápida — Waste = desperdiçar/lixo.' where id = '8332eb5e-c32d-4750-9df8-58f32c581f31' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Use TELL quando há uma pessoa recebendo a informação (tell someone). Use SAY quando não menciona a pessoa (say something). Referência rápida — Tell a lie = contar uma mentira.' where id = 'bbb65c46-0143-4e39-b13b-3bf1d4ccf324' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'TRAVEL = viajar (verbo) / o ato de viajar (incontável). TRIP = uma viagem (contável, ida e volta, curta). JOURNEY = o trajeto/percurso (geralmente longo). Referência rápida — Boa viagem! = Have a good trip!.' where id = '6c5746bb-a4df-4374-82c0-ebacc76bd12e' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'WIN = ganhar um prêmio/jogo/competição (win a game, win a prize). BEAT = vencer/derrotar um oponente (beat someone). Não diga ''win someone''. Referência rápida — Vencemos o time deles = We beat their team.' where id = 'b75d82b8-cde7-4bac-b84a-de83061be1ed' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'MISS tem dois sentidos: perder (não pegar/alcançar) — miss the bus, miss a class; e sentir falta/saudade — I miss you. Referência rápida — lose (miss = não pegar).' where id = '6f5ba665-5c93-451f-a51f-7f72d03419a9' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'HOLD: hold on (esperar/segurar), hold up (atrasar; assaltar), hold back (conter-se/reter), hold out (aguentar), hold in (segurar emoção). Referência rápida — hold on = aguarde na linha.' where id = '3d1e01a8-495a-4fc5-bff7-a8bdd528a2ae' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Muitos idioms usam animais. Ex.: hold your horses (calma), let the cat out of the bag (revelar segredo), a piece of cake (fácil). Referência rápida — Kill two birds with one stone = resolver duas coisas de uma vez; When pigs fly = nunca (impossível); The elephant in the room = problema óbvio ignorado.' where id = '1b63cef5-62e3-44d2-b079-0f8bf3896faa' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Idioms com números: second to none (o melhor de todos), at the eleventh hour (na última hora), a dime a dozen (comum/barato), on cloud nine (nas nuvens). Referência rápida — Put two and two together = deduzir/juntar as peças; In two minds = indeciso; The whole nine yards = tudo, completo.' where id = 'd87e2532-3116-4eb7-81fc-77dded3fc233' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'LIKE + substantivo = parecido com (sings like an angel). AS + função/cargo = na condição de (works as a teacher). AS + oração = como/conforme (as I said). Referência rápida — AS = função real; Funciona de mesa = as; Such as = como por exemplo.' where id = 'c97f62fd-c0e4-4b6f-b017-8616a21a4a71' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'SEE = ver sem esforço (I see a bird); LOOK = olhar direcionado (look at this); WATCH = assistir com atenção prolongada (watch TV). See a movie no cinema, watch TV em casa! Referência rápida — See = percepção; Let me see = deixa eu pensar/ver; Watch out! = cuidado!.' where id = '4530d1aa-c1ac-4d25-b499-d5f8e7ab04d0' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Cores aparecem em muitos idioms: feel blue (triste), green with envy (com inveja), once in a blue moon (raramente), red tape (burocracia). Referência rápida — Caught red-handed = pego no flagrante; A grey area = área indefinida/duvidosa.' where id = 'eb89f4a5-c5a6-4106-9e41-50da2035fe6b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Idioms com comida: spill the beans (revelar segredo), bring home the bacon (sustentar a casa), in a nutshell (resumindo), the icing on the cake (a cereja do bolo). Referência rápida — A hard nut to crack = algo/alguém difícil; Have bigger fish to fry = ter coisas mais importantes.' where id = '8468732a-beaf-41c0-94d2-71233ad3cc98' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Idioms de dinheiro: cost a fortune (custar uma fortuna), tighten your belt (economizar), break the bank (custar caro demais), rip-off (roubo, caro). Referência rápida — Save up = juntar dinheiro; Live from hand to mouth = viver no aperto.' where id = 'e153f6d3-fee8-4563-ae2e-7905b2df7d30' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'A confirmação no fim da frase: You''re Brazilian, aren''t you? Frase positiva → tag negativa; frase negativa → tag positiva. O verbo auxiliar comanda. Referência rápida — Past simple → didn''t; Have → haven''t.' where id = 'e3aac3cc-8a2a-4f14-b11f-52bb9924f036' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'REMEMBER = lembrar sozinho (I remember his name). REMIND = alguém/algo te faz lembrar (Remind me to call / This song reminds me of you). Referência rápida — Remember + -ing = memória; Set a reminder = criar um lembrete.' where id = '23ed0619-39b3-4036-bfb1-8a9ffee23d1a' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'LOSE = perder posse/jogo (lose keys, lose a match). MISS = perder por não estar lá (miss the bus, miss a class) e sentir falta (I miss you). Referência rápida — Derrota = lose; Get lost! = cai fora!.' where id = 'f1b68f72-041e-4fb4-9c12-28e3ea944dbe' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'FUN = divertido/prazeroso (the party was fun). FUNNY = engraçado, que faz rir (a funny joke) — ou estranho (a funny smell!). A festa é fun; o palhaço é funny. Referência rápida — Have fun! = divirta-se!; Make fun of = zombar de.' where id = '4da65537-7a21-4fea-95b4-fc3ea4553071' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Falsos amigos adverbiais: actually = na verdade (não ''atualmente''!); eventually = no fim, após um tempo (não ''eventualmente''!); currently = atualmente; occasionally = eventualmente/às vezes. Referência rápida — Eventually = no fim, finalmente; Ultimately = em última análise.' where id = '78cfe81c-da29-48cb-9807-8ed4c465defe' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'LIE (lie-lay-lain) = deitar-se (sem objeto). LAY (lay-laid-laid) = colocar/deitar ALGO (com objeto). Confusão clássica até para nativos. Referência rápida — lie(mentir) → lied.' where id = '4e738c13-b8bf-42bc-a038-6f6fbb255a13' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'TAKE: take off (decolar/tirar roupa), take up (começar hobby), take after (puxar a/parecer), take over (assumir), take back (devolver/retirar o que disse). Referência rápida — Take off your coat = tire o casaco.' where id = '424279a9-9499-4732-adb2-e430b268d550' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'WAIT = aguardar (tempo passar). HOPE = torcer/desejar que algo bom aconteça. EXPECT = esperar/prever (achar que vai acontecer). Referência rápida — She is expecting = Ela está grávida (esperando bebê).' where id = '6841bf5f-43b6-49d3-8df8-367e1399653e' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Prefixos que invertem o sentido: un- (unhappy), in-/im-/il-/ir- (impossible, illegal, irregular), dis- (dislike), non- (non-stop). Referência rápida — Non-stop = sem parar.' where id = '4a66e4aa-d4ff-4da1-a396-817ae1df84d4' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Cada futuro tem seu papel: WILL para decisões na hora e previsões de opinião; GOING TO para planos e evidências; PRESENT CONTINUOUS para compromissos já agendados. Referência rápida — Horário fixo = present simple.' where id = 'fceb7aa3-1212-4618-8365-606e4343c113' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Verbos de estado não usam -ing: know, believe, love, hate, own, need, seem, belong. Descrevem estados, não ações: I know ✅, I am knowing ❌. Referência rápida — Opinião = think; ponderar = thinking.' where id = 'df23e9ea-23e6-474a-9f1a-f78c93468749' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Alguns verbos mudam de sentido: stop smoking (parar de fumar) × stop to smoke (parar para fumar); remember doing (lembrar de ter feito) × remember to do (lembrar de fazer); try doing (experimentar) × try to do (esforçar-se). Referência rápida — Try opening the window = experimente abrir.' where id = 'bda159c5-89db-41ad-9408-d0412a1c3d61' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Concordar como nativo: ''I love coffee.'' — ''So do I'' (eu também). ''I don''t smoke.'' — ''Neither do I'' (nem eu). O auxiliar copia o da frase original. Referência rápida — Nem eu = negativa.' where id = 'e96d7fb6-3797-464c-bf9e-d1d079d40456' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Além do much/many: plenty of (de sobra), a great deal of (uma grande quantidade — incontável), several (vários), hardly any (quase nenhum), loads of (um monte — informal). Referência rápida — The vast majority of = a grande maioria de.' where id = '990ceea4-00c9-4a1d-a06b-28251adb47d5' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Another + singular (mais um: another coffee); other + plural/incontável (outros: other people); others sozinho (os outros: the others); the other = o outro (de dois). Referência rápida — Each other = um ao outro (mútuo).' where id = 'd7356511-15c8-4712-95eb-379ef5791b65' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'COM ''a'' = positivo (tem um pouco): a little water, a few friends. SEM ''a'' = negativo (quase nada): little hope (pouca esperança), few options (poucas opções). Little/a little = incontável; few/a few = contável. Referência rápida — Quite a few = bastante (muitos!).' where id = 'd169a176-3a49-4364-a655-18e67d7553ed' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'STILL = ainda continua (still working); YET = ainda não / já? (em negativas e perguntas, no fim); ALREADY = já (antes do esperado): I''ve already eaten. Referência rápida — Still + negativa = ênfase.' where id = '7e437110-3b25-4417-9ac7-59ba9b16bb8e' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'BY = até (prazo final — a ação acontece ANTES ou NO momento): finish by Friday. UNTIL = até (duração contínua — a ação dura ATÉ lá): work until 6pm. Referência rápida — Espera contínua = until.' where id = '0dc75808-a368-4180-af28-454f7d825fd4' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'DURING + substantivo (during the meeting); WHILE + frase com verbo (while I was talking); FOR + duração em tempo (for two hours). Referência rápida — Meanwhile = enquanto isso.' where id = '00e1160b-24d2-4703-a8c9-14707592bc64' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'EVEN THOUGH + fato real (embora — aconteceu mesmo): Even though it rained, we went. EVEN IF + hipótese (mesmo que — talvez nem aconteça): Even if it rains, we''ll go. Referência rápida — As if = como se (irreal).' where id = '1892b7fc-54d4-4933-af9a-e58d4f05259f' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'COME = em direção a quem fala/ouve; GO = para longe. Pegadinha: em convites, o inglês usa COME mesmo quando ''vamos'': I''m coming to your party (vou à sua festa!). Referência rápida — Commute = trajeto diário.' where id = '559b1863-769c-4383-99eb-67cf1c68a413' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Debata sem brigar: I couldn''t agree more (concordo total), You have a point (você tem razão nisso), I see what you mean, but... (entendo, mas), I''m not so sure about that (não sei não), Fair enough (justo). Referência rápida — Fair enough = justo, faz sentido.' where id = 'e5428fc3-bbdb-424c-b2bf-60a78e2fd853' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Idioms de clima: under the weather (indisposto), a storm in a teacup (tempestade em copo d''água), come rain or shine (aconteça o que acontecer), on cloud nine (nas nuvens). Referência rápida — A storm in a teacup = exagero por algo pequeno; On cloud nine = muito feliz; Take a rain check = deixar para outra hora; A ray of sunshine = pessoa que alegra.' where id = '45830915-e234-4e66-8477-df80eb91ccb0' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Palavras de sentido parecido carregam emoções diferentes. ''Determined'' (positivo) vs ''stubborn'' (negativo). Referência rápida — skinny = magro demais (negativo); Nosy = Intrometido (negativo).' where id = 'c1181e34-35aa-48ea-abd3-9f52185a5d89' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Na fala natural as palavras se fundem: going to → gonna, want to → wanna, got to → gotta. Só na fala/informal. Referência rápida — Lemme = let me; Gimme = give me.' where id = 'b2c4edc5-914c-4dba-8a09-47633d6494e3' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Idioms com o corpo são comuns: cost an arm and a leg (caríssimo), pull someone''s leg (brincar), get cold feet (amarelar), off the top of my head (de cabeça). Referência rápida — Keep an eye on = ficar de olho em; A pain in the neck = algo/alguém chato.' where id = '9f932eb4-c071-4a30-86d3-6473c534d808' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Provérbios são ditados de sabedoria popular: actions speak louder than words, better late than never, practice makes perfect, the early bird catches the worm. Referência rápida — The early bird catches the worm = quem cedo madruga..; When in Rome, do as the Romans = adapte-se ao lugar.' where id = 'b24e59f0-3bb9-4f24-8767-44e3519550a8' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Alguns verbos mudam de sentido: ''stop smoking'' (parar de fumar) vs ''stop to smoke'' (parar para fumar). ''remember doing'' (lembrar de algo feito) vs ''remember to do'' (lembrar de fazer). ''try doing'' (experimentar) vs ''try to do'' (esforçar-se). Referência rápida — remember + -ing = passado; try + -ing = experimentar.' where id = '25d70f37-518d-42f3-9b4d-7a2a0f62d9e4' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'A sílaba tônica e a entonação mudam o sentido. ''PREsent'' (substantivo) x ''preSENT'' (verbo). A entonação ascendente sugere pergunta ou dúvida. Referência rápida — Tônica final = verbo.' where id = '0c3a6ac4-5f90-4919-a94f-f1af51a5c184' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Textos técnicos e jurídicos usam termos formais e fixos: ''hereby'' (pelo presente), ''pursuant to'' (conforme), ''terms and conditions'', ''liability'' (responsabilidade). Referência rápida — Plaintiff = autor da ação.' where id = '3d60c81e-4fb0-477d-94cc-7f8ffe99c87e' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Negociar em inglês usa linguagem condicional e diplomática: ''If you could..., we would...'', ''We''re prepared to..., provided that...''. Referência rápida — meet halfway = chegar a um meio-termo.' where id = 'd36e51a6-c219-4b84-94fa-cd688d6fba67' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'A escrita refinada usa coesão (linkers variados), precisão lexical, variação de estruturas e parágrafos com tópico claro. Referência rápida — Nevertheless = não obstante/mesmo assim.' where id = '0a27bab6-4731-4958-ba0a-0babc55c3d51' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Sufixos mudam a classe da palavra: -tion/-ment (substantivo: information), -ness (happiness), -ful/-less (careful/careless), -ly (advérbio: quickly), -able (comfortable). Referência rápida — -less = sem (careless = sem cuidado).' where id = '484136e9-3ce9-4efc-830d-93bd128f6b87' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Condicionais mistas combinam tempos. Passado->presente: ''If I had studied (passado), I would be rich now (presente)''. Presente->passado: ''If I were rich (agora), I would have bought it (antes)''. Referência rápida — Presente habitual → passado.' where id = '994c5b5c-ab41-4e32-bbdc-cbb558808aef' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Estrutura formal para relatar rumores/opiniões: ''It is said that he is rich'' ou ''He is said to be rich''. Comum em notícias. Verbos: say, believe, think, know, report, expect. Referência rápida — It is known that = sabe-se que.' where id = 'c21867aa-947e-42da-b0f9-a8da48931768' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Podemos encurtar orações relativas. Ativa: ''the man WHO IS standing'' -> ''the man standing''. Passiva: ''the book WHICH WAS written'' -> ''the book written''. Corta o pronome relativo + verbo be. Referência rápida — Ativa → waiting.' where id = '8c8a282d-50dd-49c9-a90b-e861144e1a17' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Conectores ligam ideias em texto formal. Contraste: however, nevertheless, on the other hand. Resultado: therefore, thus, consequently. Adição: moreover, furthermore. Geralmente vem com vírgula. Referência rápida — Nevertheless = mesmo assim.' where id = '58978697-788f-4c62-a184-1d064ac8c26b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Prefixos mudam sentido: un- (unhappy, unfair), in-/im-/ir- (impossible, irregular), dis- (disagree, dishonest), mis- (misunderstand = entender errado), over- (overwork = trabalhar demais), under- (underestimate = subestimar). Referência rápida — Over- = demais/em excesso.' where id = '3a9d1b3c-7c8c-4b47-946e-5f29ba3c66f3' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'RAISE (transitivo: levantar algo - raise your hand) x RISE (intransitivo: subir sozinho - prices rise). LIE (deitar-se: lie/lay/lain) x LAY (colocar algo: lay/laid/laid). Confundir é comum até para nativos. Referência rápida — rise → rose.' where id = 'aa5ea396-8b1b-406b-ada5-2a113c4f6d75' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Sufixos que refinam: -esque (ao estilo de: picturesque), -ish (meio/aproximado: fortyish), -worthy (digno de: noteworthy), -proof (à prova de: foolproof), -free (livre de: sugar-free). Referência rápida — Fortyish = uns quarenta e poucos; Noteworthy = digno de nota; Waterproof = à prova d''água; Sugar-free = sem açúcar; Kafkaesque = absurdo como em Kafka.' where id = 'e0c0a78f-9c06-426f-9ccc-6f656bda7157' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O inglês corporativo é cheio de expressões idiomáticas. Reconhecê-las é essencial em reuniões internacionais. Referência rápida — To be on the same page = estar de acordo; The bottom line = o ponto principal; To get the ball rolling = dar início; A win-win situation = bom para os dois lados.' where id = '356929c7-554b-4bd0-80b5-2aaa36544952' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Phrasal verbs de três partes (verbo + advérbio + preposição) nunca se separam e têm sentido idiomático. Referência rápida — come up with = bolar/inventar; run out of = ficar sem; put up with = tolerar; get along with = se dar bem com.' where id = '671fcc67-803f-4fd9-959b-7d6509e4bf8a' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Números além da matemática: back to square one (voltar à estaca zero), on cloud nine (nas nuvens), two-faced (falso), at sixes and sevens (confuso), a one-track mind (só pensa numa coisa). Referência rápida — On cloud nine = muito feliz; Two-faced = falso, hipócrita; It takes two to tango = a culpa é dos dois; The eleventh hour = o último momento.' where id = 'ec9eb5e6-ac1d-4427-b117-15b77d3f0297' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O inglês corporativo adora compostos: game-changer (divisor de águas), deal-breaker (fator eliminatório), must-have (indispensável), know-how (conhecimento prático), breakthrough (avanço revolucionário). Referência rápida — Game-changer = algo que muda tudo; Deal-breaker = o que inviabiliza o acordo; Must-have = item indispensável; A win-win situation = bom para os dois lados.' where id = 'fc473ea7-c583-4eff-9557-3344e7c5fbb7' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'A posição muda o sentido: Only I love you (só eu te amo) ≠ I only love you (eu só te amo, nada mais) ≠ I love only you (amo só você). O advérbio gruda no que modifica. Referência rápida — Only I can do it = só eu posso fazer; Even John came = até o John veio; Just arrived = acabou de chegar; I just want to talk = eu só quero conversar.' where id = 'dbf52ab4-4ecf-4d73-9c51-8243bf84dba8' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Manchetes de jornal usam gramática própria: omitem artigos, usam presente para o passado e infinitivo para o futuro. Referência rápida — Presente = passado jornalístico; Quake hits city = Terremoto atingiu a cidade; due = previsto/esperado.' where id = 'a0e0ed33-bbd0-418f-9550-d79bc942bbd4' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'A tradição naval marcou o inglês: in the same boat (no mesmo barco), learn the ropes (pegar o jeito), miss the boat (perder a chance), plain sailing (tranquilo), weather the storm (aguentar a crise). Referência rápida — Plain sailing = fácil, sem problemas; Show someone the ropes = ensinar o básico; In the same boat = na mesma situação.' where id = 'a93b4448-9c70-4411-9825-68f98d097030' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Idioms nascidos nos campos de batalha: bite the bullet (encarar o inevitável), stick to your guns (manter sua posição), drop a bombshell (soltar uma bomba), up in arms (revoltado), fight a losing battle (lutar por causa perdida). Referência rápida — Bite the bullet = encarar algo difícil; Drop a bombshell = dar notícia chocante; Keep your head down = evitar chamar atenção.' where id = '98a24c36-3b04-4bc6-97b0-66971cbc7305' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O inglês formal e acadêmico usa termos latinos: per se (em si), vice versa, etc. (e assim por diante), i.e. (isto é), e.g. (por exemplo). Referência rápida — per se = em si mesmo; vice versa = o contrário também.' where id = '73194e37-5a0d-47c0-bfc8-6bbe1a8fb308' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Na fala rápida, nativos reduzem palavras: going to → gonna, want to → wanna, kind of → kinda. Comuns ao ouvir, mas evite na escrita formal. Referência rápida — gotta = got to (ter que); lemme = let me.' where id = '6ff1e35b-6712-409c-9b17-cb990f1f8302' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Tempo é idiom: in the nick of time (em cima da hora), around the clock (24 horas por dia), call it a day (encerrar por hoje), against the clock (contra o relógio), time flies (o tempo voa). Referência rápida — Time flies = o tempo passa rápido; For the time being = por enquanto.' where id = 'b63900dd-9e2a-4d8d-9c9c-8c7b28ecf951' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Aposente o ''very good'': decent (razoável), solid (consistente), remarkable (notável), superb (soberbo), outstanding (excepcional), top-notch (de primeira). Suba a régua do elogio. Referência rápida — Top-notch = de primeira linha; Remarkable = digno de nota.' where id = '63d56092-7481-4a95-802e-105b66d325d7' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O inglês chique fala francês: déjà vu (sensação de já vivido), faux pas (gafe), cliché (clichê), fiancé/fiancée (noivo/a), résumé (currículo, AmE). Pronúncia afrancesada e tudo. Referência rápida — ideia batida = Cliché; Entrepreneur = empreendedor.' where id = '6b3196d6-2eae-4eb5-b6aa-024e5fb887f7' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Binômios são pares de palavras em ordem fixa ligados por "and" ou "or". Invertê-los soa estranho para nativos. Referência rápida — Pros and cons = prós e contras.' where id = '929e38f1-65b9-46b2-9729-68f414993210' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Advérbios de grau ajustam a força de um adjetivo: utterly/absolutely (muito forte), fairly/somewhat (moderado), slightly (leve). Referência rápida — Slightly = levemente.' where id = 'aea6b7d7-4cbe-4e0e-a9df-6598b681dd3e' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Conectores formais dão fluidez a textos avançados: moreover (além disso), nevertheless (ainda assim), thus/thereby (assim), whereas (ao passo que). Referência rápida — thus = assim/portanto.' where id = '7dabffdd-e3de-4891-890d-63e7bfb8ce22' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Em inglês, pedidos diretos podem soar rudes. Falantes avançados suavizam com estruturas indiretas: "I was wondering if...", "Would you mind...", "Could you possibly...". Referência rápida — ''Not at all'' = sem problema.' where id = '967dabe9-cbbd-4829-9fec-f357c0b53ebc' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Nominalização é transformar verbos/adjetivos em substantivos (decide -> decision; fail -> failure). É a marca do inglês formal e acadêmico, tornando o texto mais denso e impessoal. Referência rápida — grow → growth.' where id = '05c0b34b-1149-442a-b1ea-c4f24622b897' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O inglês formal usa expressões latinas: per se (em si), vice versa (o contrário também), e.g. (por exemplo), i.e. (isto é), etc., versus, status quo, ad hoc. Referência rápida — status quo = situação atual.' where id = '80c6a1d0-6c31-4f7c-a08f-ce2fbc6fc042' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Gírias atuais do inglês informal: to ghost (sumir sem responder), to flex (ostentar), low-key (discretamente/meio que), salty (irritado), lit (incrível). Referência rápida — To flex = ostentar/se exibir.' where id = '23fd437d-d0e4-479d-8cb7-4a4ad9a45c09' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Clima vira sentimento: under the weather (indisposto), a storm in a teacup (tempestade em copo d''água), take a rain check (fica pra próxima), on cloud nine (nas nuvens/muito feliz), steal someone''s thunder (roubar a cena). Referência rápida — A storm in a teacup = exagero por algo pequeno.' where id = '4e2fdbfc-4956-4a7b-a141-898ca8d4f894' and explicacao not like '%Referência rápida%';
update licoes set explicacao = '''Big'' tem nuances: large (grande, neutro/formal), huge (enorme), vast (vasto - areas/quantidades), enormous/immense (imenso), gigantic (gigantesco). A escolha muda a intensidade e o registro. Referência rápida — massive = informal enfático.' where id = '3a4393a4-cceb-440e-b935-7cf83cf40a26' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Graus de raiva: annoyed/irritated (irritado, leve), cross (chateado, UK), mad (bravo, US informal), furious (furioso), livid/enraged (fora de si). A intensidade importa muito no tom. Referência rápida — Livid = furioso ao extremo.' where id = 'e8fb4aa0-ef42-432a-8f56-062fe990ec7b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Cores pintam a fala nativa: out of the blue (do nada), once in a blue moon (raramente), green with envy (morrendo de inveja), red tape (burocracia), white lie (mentirinha inofensiva). Referência rápida — Caught red-handed = pego no flagra.' where id = 'dcb058f6-aae8-40ce-847f-db1c14235639' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O esporte invadiu o escritório: the ball is in your court (a decisão é sua), move the goalposts (mudar as regras no meio do jogo), throw in the towel (jogar a toalha), ballpark figure (número aproximado), level playing field (condições iguais). Referência rápida — Get the ball rolling = dar o pontapé inicial.' where id = '5f0358a4-2482-4322-a6f1-4345391d55f9' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'GET é o canivete suíço do inglês: get away with (sair impune), get around to (finalmente fazer), get by (se virar), get over (superar), get carried away (empolgar-se demais). Referência rápida — Get out of (doing something) = escapar de uma obrigação.' where id = '50f73b7a-67bc-4696-9d08-0724599cd25b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Chega de só ''sad'': down (na fossa), gloomy (melancólico), miserable (infeliz), heartbroken (de coração partido), devastated (arrasado). Cada um tem uma intensidade. Referência rápida — Miserable = muito infeliz.' where id = '44872469-af22-40d7-b1aa-5ec5013f79a1' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Pra baixo também há escala: mediocre (medíocre), lousy (vagabundo), dreadful (horrível), appalling (chocante de ruim), atrocious (atroz). ''Mediocre'' fere mais que ''bad'' em crítica. Referência rápida — Mediocre = sem brilho, mais ou menos.' where id = '6309b271-4b15-44e0-a52c-17de61ae08d1' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Diga adeus ao ''said'': whisper (sussurrar), mutter (resmungar), yell (gritar), claim (alegar), admit (admitir). O verbo certo pinta a cena inteira. Referência rápida — Ele deixou escapar = he blurted out.' where id = 'd60f87cd-2639-438d-b60c-bf8cd18f03d3' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Olhar tem intenção: glance (olhada rápida), stare (encarar), gaze (contemplar), peek (espiar), glare (fuzilar com os olhos). Referência rápida — Catch a glimpse of = ver de relance.' where id = 'f5d9025b-0e57-46a8-b627-6b10575cb49f' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Vocabulário emocional fino: bittersweet (agridoce), wistful (nostálgico-saudoso), smug (convencido), overwhelmed (sobrecarregado), relieved (aliviado). Referência rápida — Homesick = com saudade de casa.' where id = '52aea415-6062-46aa-b3ba-82b47143b7b1' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Concessão de alto nível: no matter what/how/where (não importa o quê/como/onde), whatever happens (aconteça o que acontecer), however hard it is (por mais difícil que seja), even so (mesmo assim), albeit (embora — formal). Referência rápida — Regardless of the cost = independentemente do custo.' where id = 'ba6756f3-a7ec-473a-b54b-8459dd21386b' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'Debata como gente grande: concede a point (reconhecer um ponto), rebut (rebater), counterargument (contra-argumento), valid point (ponto válido), play devil''s advocate (fazer o advogado do diabo). Referência rápida — I beg to differ = discordo respeitosamente.' where id = '24025ede-8a69-4099-9a29-0f28dff05d0f' and explicacao not like '%Referência rápida%';
update licoes set explicacao = 'O juridiquês que você já aceita sem ler: terms and conditions (termos e condições), hereby (por meio deste), notwithstanding (não obstante), null and void (sem efeito), breach (violação de contrato). Referência rápida — Liability = responsabilidade legal.' where id = '218f435a-5e79-473b-b2fb-58261f98b620' and explicacao not like '%Referência rápida%';
commit;
